package fr.hydrosea.abonnements.infrastructure;
import fr.hydrosea.abonnements.application.ModelesAbonnements.CommandeAjouterParticipant;import fr.hydrosea.abonnements.application.ModelesAbonnements.CommandeCreerContrat;import fr.hydrosea.abonnements.application.ModelesAbonnements.CommandeModifierContrat;import fr.hydrosea.abonnements.application.ModelesAbonnements.VueContrat;import fr.hydrosea.abonnements.application.ModelesAbonnements.VueParticipant;import fr.hydrosea.abonnements.application.PortAbonnements;import fr.hydrosea.commun.application.RegleMetierException;import fr.hydrosea.commun.application.VersionObsoleteException;import java.time.LocalDate;import java.util.List;import java.util.UUID;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class AdaptateurJdbcAbonnements implements PortAbonnements {private final JdbcTemplate jdbc;public AdaptateurJdbcAbonnements(JdbcTemplate jdbc){this.jdbc=jdbc;}private static final org.springframework.jdbc.core.RowMapper<VueContrat> CONTRAT=(r,n)->new VueContrat(r.getObject("id",UUID.class),r.getString("reference"),r.getObject("point_consommation_id",UUID.class),r.getString("nature_abonnement"),r.getObject("date_demande",LocalDate.class),r.getObject("date_effet",LocalDate.class),r.getString("statut"),r.getInt("version"));private static final org.springframework.jdbc.core.RowMapper<VueParticipant> PARTICIPANT=(r,n)->new VueParticipant(r.getObject("id",UUID.class),r.getObject("contrat_id",UUID.class),r.getObject("tiers_id",UUID.class),r.getString("role_contractuel"),r.getBoolean("principal"),r.getBoolean("responsabilite_financiere"),r.getObject("date_creation",java.time.OffsetDateTime.class));
 public List<VueContrat> lister(){return jdbc.query("SELECT id,reference,point_consommation_id,nature_abonnement,date_demande,date_effet,statut,version FROM abo.contrat_abonnement WHERE date_suppression IS NULL ORDER BY date_creation DESC LIMIT 100",CONTRAT);}public VueContrat obtenir(UUID id){return jdbc.queryForObject("SELECT id,reference,point_consommation_id,nature_abonnement,date_demande,date_effet,statut,version FROM abo.contrat_abonnement WHERE id=?",CONTRAT,id);}public VueContrat creer(UUID id,String ref,CommandeCreerContrat c,UUID correlation){jdbc.update("INSERT INTO abo.contrat_abonnement(id,reference,point_consommation_id,nature_abonnement,date_demande,date_effet) VALUES (?,?,?,?,?,?)",id,ref,c.point(),c.nature(),c.demande(),c.effet());jdbc.update("INSERT INTO abo.historique_etat_contrat(contrat_id,etat,version_contrat,correlation_id) VALUES (?,'BROUILLON',1,?)",id,correlation);return obtenir(id);}public VueContrat modifier(UUID id,int version,CommandeModifierContrat c){if(jdbc.update("UPDATE abo.contrat_abonnement SET nature_abonnement=COALESCE(?,nature_abonnement),version=version+1,date_modification=now() WHERE id=? AND version=? AND statut='BROUILLON'",c.nature(),id,version)==0)throw new VersionObsoleteException();return obtenir(id);}
 public VueParticipant ajouterParticipant(UUID contrat,CommandeAjouterParticipant c){UUID id=UUID.randomUUID();boolean principal="TITULAIRE_PRINCIPAL".equals(c.role());jdbc.update("INSERT INTO abo.participation_contrat(id,contrat_id,tiers_id,role_contractuel,principal,responsabilite_financiere,periode) VALUES (?,?,?,?,?,?,daterange(?,NULL,'[)'))",id,contrat,c.tiers(),c.role(),principal,c.responsabilite(),c.debut());return jdbc.queryForObject("SELECT id,contrat_id,tiers_id,role_contractuel,principal,responsabilite_financiere,date_creation FROM abo.participation_contrat WHERE id=?",PARTICIPANT,id);}public VueContrat valider(UUID id,int version,UUID correlation){if(compter("SELECT count(*) FROM abo.participation_contrat WHERE contrat_id=? AND principal AND role_contractuel='TITULAIRE_PRINCIPAL' AND responsabilite_financiere AND upper_inf(periode)",id)!=1)throw new RegleMetierException("Le Contrat exige exactement un titulaire principal actif et financièrement responsable.");changer(id,version,"BROUILLON","A_VALIDER");historiser(id,"A_VALIDER",version+1,correlation);changer(id,version+1,"A_VALIDER","VALIDE");historiser(id,"VALIDE",version+2,correlation);return obtenir(id);}public VueContrat activer(UUID id,int version,UUID correlation){VueContrat c=obtenir(id);if(!"VALIDE".equals(c.statut()))throw new RegleMetierException("CTR-CONTRAT-NON-VALIDE","Le Contrat doit être validé avant son activation.");String etat=jdbc.queryForObject("SELECT statut FROM des.point_consommation WHERE id=?",String.class,c.pointConsommationId());if(!"OUVERT".equals(etat))throw new RegleMetierException("CTR-POINT-CONSOMMATION-NON-OUVERT","Le Point de consommation doit être ouvert.");if(compter("SELECT count(*) FROM des.liaison_desserte_consommation WHERE point_consommation_id=? AND periode @> now()",c.pointConsommationId())==0)throw new RegleMetierException("CTR-RATTACHEMENT-ABSENT","Le Point ne possède aucun rattachement actif.");if(compter("SELECT count(*) FROM abo.participation_contrat WHERE contrat_id=? AND principal AND role_contractuel='TITULAIRE_PRINCIPAL' AND responsabilite_financiere AND periode @> ?::date",id,c.dateEffet())!=1)throw new RegleMetierException("CTR-TITULAIRE-PRINCIPAL-INCOHERENT","Le titulaire principal doit couvrir la date d’effet et porter la responsabilité financière.");if(c.dateEffet().isBefore(c.dateDemande()))throw new RegleMetierException("CTR-DATE-EFFET-INCOHERENTE","La date d’effet ne peut pas précéder la demande.");if(compter("SELECT count(*) FROM abo.contrat_abonnement WHERE point_consommation_id=? AND statut='ACTIF' AND id<>?",c.pointConsommationId(),id)>0)throw new RegleMetierException("CTR-CONTRAT-ACTIF-EXISTANT","Un autre Contrat actif existe déjà pour ce Point.");changer(id,version,"VALIDE","ACTIF");historiser(id,"ACTIF",version+1,correlation);return obtenir(id);}
 public String prochaineReference(){Long n=jdbc.queryForObject("SELECT nextval('abo.reference_contrat_seq')",Long.class);return "CA-%d-%06d".formatted(LocalDate.now().getYear(),n);}private void changer(UUID id,int version,String source,String cible){if(jdbc.update("UPDATE abo.contrat_abonnement SET statut=?,version=version+1,date_modification=now() WHERE id=? AND version=? AND statut=?",cible,id,version,source)==0)throw new VersionObsoleteException();}private void historiser(UUID id,String etat,int version,UUID correlation){jdbc.update("UPDATE abo.historique_etat_contrat SET date_fin_validite=GREATEST(clock_timestamp(),date_debut_validite+interval '1 microsecond') WHERE contrat_id=? AND date_fin_validite IS NULL",id);jdbc.update("INSERT INTO abo.historique_etat_contrat(contrat_id,etat,date_debut_validite,version_contrat,correlation_id) SELECT ?,?,date_fin_validite,?,? FROM abo.historique_etat_contrat WHERE contrat_id=? AND date_fin_validite IS NOT NULL ORDER BY date_fin_validite DESC LIMIT 1",id,etat,version,correlation,id);}private int compter(String sql,Object...p){Integer n=jdbc.queryForObject(sql,Integer.class,p);return n==null?0:n;}}
